import{_ as l,a0 as r,w as s,s as a,ao as u,I as e,x as t,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何用wifi-linux檢測AP信號強度 | LCTT x X-CMD","titleTemplate":false,"description":"如何用wifi-linux檢測AP信號強度 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用wifi-linux檢測AP信號強度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用wifi-linux檢測AP信號強度 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux","title":"如何用wifi-linux檢測AP信號強度","tag":"201503","desc":""},"relativePath":"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux.md","filePath":"[post].md"}'),d={name:"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux.md"};function f(g,i,x,w,h,m){const n=r("Link");return s(),a("div",null,[i[13]||(i[13]=u(`<h1 id="如何用wifi-linux檢測ap信號強度" tabindex="-1">如何用wifi-linux檢測AP信號強度 <a class="header-anchor" href="#如何用wifi-linux檢測ap信號強度" aria-label="Permalink to “如何用wifi-linux檢測AP信號強度”">​</a></h1><p>作為一名python極客，我喜歡在github上挖掘新的用於linux用户的python工具。今天我發現了一款用python寫成的用於檢測AP信號強度的工具：wifi-linux。</p><p>我已經在<strong>wifi-linux</strong>上實驗了大約兩個小時，並且它工作的很好但是我希望在不久的將來在作者那裏看到一些單元測試，因為命令<strong>plot</strong>無法在我的電腦上工作，並且會導致一些問題。</p><h3 id="什麼是wifi-linux" tabindex="-1">什麼是wifi-linux <a class="header-anchor" href="#什麼是wifi-linux" aria-label="Permalink to “什麼是wifi-linux”">​</a></h3><p>根據github上作者賬號的官方的 readme.md文件， wifi-linux是一個簡單的收集你周圍AP的RSSI信息的python腳本，它還會畫出RSSI活動圖形。</p><p>作者説可以在該程序中可以使用plot命令繪製RSSI 活動圖形，但是不幸的是，這對我不可行。wifi-linux也支持其他的命令，比如<strong>bp</strong> 來加入一個斷點，<strong>print</strong>會打印一些統計和<strong>啓動開關</strong>。</p><p>wifi-linux程序有下面這些依賴：</p><ul><li>dbus-python</li><li>gnuplot-py</li></ul><p>首先我們需要安裝所有的包依賴以使它可以運行在我們的linux機器上。</p><h3 id="安裝wifi-linux需要的包" tabindex="-1">安裝wifi-linux需要的包 <a class="header-anchor" href="#安裝wifi-linux需要的包" aria-label="Permalink to “安裝wifi-linux需要的包”">​</a></h3><p>我嘗試使用python包管理工具pip安裝python-dbus但是失敗了，因為pip會查找setup.py，但是python-dbus中沒有。因此下面的命令不工作。</p><pre><code>pip install dbus-python
</code></pre><p>你可以試一下但是很有可能會在終端中出現下面的錯誤。</p><pre><code>IOError: [Errno 2] No such file or directory: &#39;/tmp/pip_build_oltjano/dbus-python/setup.py&#39;
</code></pre><p>我該怎麼解決這個問題呢？很簡單，用下面命令中的系統包管理工具來安裝Python DBUS。</p><pre><code>sudo apt-get install python-dbus
</code></pre><p>上面的命令只有在有apt-get包管理器的機器中才可以使用，比如Debian和Ubuntu。</p><p>我們要安裝的第二個依賴是gnuplot-py。下載並用tar解壓，接着運行setup.py來安裝包。</p><p>第一步是下載gnuplot-py。</p><pre><code>wget http://prdownloads.sourceforge.net/gnuplot-py/gnuplot-py-1.8.tar.gz
</code></pre><p>接着使用tar工具解壓。</p><pre><code>tar xvf gnuplot-py-1.8.tar.gz
</code></pre><p>接着使用cd命令改變目錄。</p><pre><code>cd gnuplot-py-1.8
</code></pre><p>接着運行下面的命令在你的系統中安裝gnuplot-py。</p><pre><code>sudo setup.py install
</code></pre><p>安裝完成後，你就可以在你的系統中運行wifi-linux了。只需下載並用下面的命令運行腳本。</p><p>用下面的命令下載wifi-linux到你的機器中。</p><pre><code>wget https://github.com/dixel/wifi-linux/archive/master.zip
</code></pre><p>解壓master.zip接着使用下面的命令運行list_rsssi.py腳本。</p><pre><code>python list_rssi.py
</code></pre><p>下面的截圖説明wifi-linux在工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux.png" alt="wifi-linux to monitor wifi signal strength"></p><p>命令<strong>bp</strong>用於像下面那樣添加一個斷點。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux2.png" alt="the bp command in wifi-linux"></p><p>命令<strong>print</strong>可以用於在終端上顯示你機器的狀態。下面就是一個例子。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux3.png" alt="the print command"></p><hr>`,38)),e("p",null,[i[1]||(i[1]=t("via: ",-1)),p(n,{href:"http://linoxide.com/linux-how-to/monitor-access-point-signal-strength-wifi-linux/"},{default:o(()=>[...i[0]||(i[0]=[t("http://linoxide.com/linux-how-to/monitor-access-point-signal-strength-wifi-linux/",-1)])]),_:1})]),e("p",null,[i[5]||(i[5]=t("作者：",-1)),p(n,{href:"http://linoxide.com/author/oltjano/"},{default:o(()=>[...i[2]||(i[2]=[t("Oltjano Terpollari",-1)])]),_:1}),i[6]||(i[6]=t(" 譯者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:o(()=>[...i[3]||(i[3]=[t("geekpi",-1)])]),_:1}),i[7]||(i[7]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...i[4]||(i[4]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[10]||(i[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[8]||(i[8]=[t("LCTT",-1)])]),_:1}),i[11]||(i[11]=t(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...i[9]||(i[9]=[t("Linux中國",-1)])]),_:1}),i[12]||(i[12]=t(" 榮譽推出",-1))])])}const b=l(d,[["render",f]]);export{T as __pageData,b as default};
